        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/041.svg" width="18" height="18" alt="stats">
      </div>
      <div class="circle-btn btn" title="Settings">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/033.png" width="18" height="18" alt="gear">
      </div>
